def burnside(perms, k):
    """Number of colourings with k colours up to the group generated by
    exactly the given list of permutations (the *whole* group, including the
    identity): (1/|G|) sum k^cycles(p)."""
    total = 0
    for p in perms:
        seen, c = [False] * len(p), 0
        for i in range(len(p)):
            if not seen[i]:
                c += 1
                while not seen[i]:
                    seen[i] = True
                    i = p[i]
        total += k ** c
    assert total % len(perms) == 0
    return total // len(perms)

def necklaces(n, k, flips=False):
    """Number of necklaces (rotations) or bracelets (flips=True) with n
    beads and k colours."""
    perms = [[(i + r) % n for i in range(n)] for r in range(n)]
    if flips:
        perms += [[(r - i) % n for i in range(n)] for r in range(n)]
    return burnside(perms, k)
